L2_1.m_Talk_KOREA = "생각보다 시간 오차가 크군."
L2_1.m_fTalkTime = 0.03
L2_1.m_Talk_JPN = "思ったより時間のズレが大きいな。"
L2_1.m_Talk_ENG = "The temporal gap is actually wider than I thought."
L2_1.m_Talk_TWN = "沒想到時間誤差比想像中的還要大。"
L2_1.m_Talk_THA = "ช่องว่างของเวลากว้างกว่าที่คิดไว้นะ"
