L2_1.m_Talk_FRA = "L'écart temporel est plus grand que ce que je pensais."
L3_1 = {}
L3_1.m_CutScenKey_Talk = "EP5_ACT2_STAGE4_START@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 175
L3_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L3_1.m_Pos = "C"
L3_1.m_Talk_KOREA = "아무래도 차원 계면을 돌파하면서 시공간 비틀림이 생긴 모양이야."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "どうやら次元界面を突破するときに、時空の歪みが発生したようだ。"
L3_1.m_Talk_ENG = "Spatiotemporal distortion might have happened while we passed through the dimension surface."
L3_1.m_Talk_TWN = "看來在突破次元界面時，時空好像發生了扭曲。"
L3_1.m_Talk_THA = "ความบิดเบือนทางกาลอวกาศอาจเกิดขึ้นตอนที่เราผ่านพื้นผิวมิติ"
L3_1.m_Talk_VTN = "Sự biến dạng không gian có thể đã xảy ra khi chúng ta đi qua biên giới thứ nguyên."
L3_1.m_Talk_SCN = "看来是突破次元界面时空时，出现了扭曲。"
L3_1.m_Talk_DEU = "Beim Durchbrechen der Dimensionsoberfläche könnte es zu einer raumzeitlichen Verzerrung gekommen sein."
L3_1.m_Talk_FRA = "Une distorsion spatiotemporelle a dû se produire quand nous avons traversé la surface de la dimension."
L4_1 = {}
