L4_1.m_Talk_KOREA = "타이밍을 맞추려면 서둘러야겠는데?"
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "間に合わせるには、急がねばならんな。"
L4_1.m_Talk_ENG = "We'd better hurry, or we won't be able to get there on time."
L4_1.m_Talk_TWN = "我們要趕上時機，可能要快一點了。"
L4_1.m_Talk_THA = "เราควรเร่งมือนะ ไม่งั้นเราจะไปถึงที่นั่นไม่ทันเวลา"
L4_1.m_Talk_VTN = "Tốt hơn là chúng ta nên nhanh lên, nếu không chúng ta sẽ không thể đến đó đúng giờ."
L4_1.m_Talk_SCN = "我们要对上时机的话，也许要抓紧时间了？"
L4_1.m_Talk_DEU = "Wir müssen uns beeilen, sonst schaffen wir es nicht rechtzeitig!"
L4_1.m_Talk_FRA = "On ferait mieux de se dépêcher si on veut arriver à l'heure."
