L8_1.m_Pos = "L"
L8_1.m_Talk_KOREA = "생각했던 것보다 주변의 침식체 수가 많아."
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "思ったより、周りにいる侵食体の数が多い。"
L8_1.m_Talk_ENG = "There are more C.O.s than expected."
