L8_1.m_Talk_THA = "มีวัตถุคอร์รัปต์เยอะกว่าที่คิด"
L8_1.m_Talk_VTN = "Có nhiều V.T.B.A.M hơn dự kiến."
L8_1.m_Talk_SCN = "周围的侵蚀体，比我们想象中的要多啊。"
L8_1.m_Talk_DEU = "Es gibt mehr C. O.s als erwartet."
L8_1.m_Talk_FRA = "Il y a beaucoup plus d'O.C. que prévu."
L9_1 = {}
L9_1.m_CutScenKey_Talk = "EP5_ACT2_STAGE4_START@9#Talk"
L9_1.m_CutScenProcessKey = 9
