L9_1.m_Pos = "L"
L9_1.m_Talk_KOREA = "호위 병력 같은 걸까?"
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "護衛役なのかな？"
L9_1.m_Talk_ENG = "Are they some kind of escort?"
L9_1.m_Talk_TWN = "就像衛兵一樣吧？"
L9_1.m_Talk_THA = "พวกนี้เหมือนผู้อารักขารึเปล่านะ?"
L9_1.m_Talk_VTN = "Chúng có phải là người hộ tống không?"
L9_1.m_Talk_SCN = "就如同护卫军一样吗？"
L9_1.m_Talk_DEU = "Sind sie eine Art Begleitschutz?"
L9_1.m_Talk_FRA = "C'est un genre d'escorte ?"
L10_1 = {}
L10_1.m_CutScenKey_Talk = "EP5_ACT2_STAGE4_START@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 175
L10_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L10_1.m_Pos = "R"
L10_1.m_Talk_KOREA = "......어보미네이션을 중심으로 모여 있는 것 보면 그렇다고 봐야겠지."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "……アボミネーションを中心として集まってるから、きっとそうだろう。"
L10_1.m_Talk_ENG = "I guess they are, considering they're surrounding the Abomination."
L10_1.m_Talk_TWN = "……從它們以憎惡為中心聚集的樣子來看，應該是這樣沒錯。"
L10_1.m_Talk_THA = "น่าจะใช่นะ ดูจากที่พวกมันไปอยู่รอบๆ อะบอมิเนชั่น"
L10_1.m_Talk_VTN = "Tôi đoán là chúng đang vây quanh Abomination."
L10_1.m_Talk_SCN = "……看他们以“憎恶”为中心聚集，应该是这样的。"
L10_1.m_Talk_DEU = "Ich denke schon, wenn man sich anschaut, wie sie die Abscheulichkeit umringen …"
L10_1.m_Talk_FRA = "Je dirai que oui, étant donné qu'ils entourent l'abomination."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "EP5_ACT2_STAGE4_START@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 175
L11_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L11_1.m_bWaitClick = true
