L11_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L11_1.m_Pos = "R"
L11_1.m_Talk_KOREA = "아마 평범한 침식체들은 아닐 거다."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "たぶん普通の侵食体ではないと思うぞ。"
L11_1.m_Talk_ENG = "They can't be any ordinary C.O.s."
L11_1.m_Talk_TWN = "大概不是一般的侵蝕體吧。"
L11_1.m_Talk_THA = "พวกมันไม่ใช่วัตถุคอร์รัปต์ธรรมดาแน่"
L11_1.m_Talk_VTN = "Chúng không thể là V.T.B.A.M bình thường được."
L11_1.m_Talk_SCN = "应该不是一般的侵蚀体。"
L11_1.m_Talk_DEU = "Das können keine gewöhnlichen C. O.s sein."
L11_1.m_Talk_FRA = "Ça peut pas être des O.C. ordinaires."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "EP5_ACT2_STAGE4_START@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 175
L12_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L12_1.m_Pos = "R"
L12_1.m_Talk_KOREA = "공명파 발생기로 조종하고 있거나 리플레이서 놈들이 만들어 낸 붕괴체 실패작들이겠지."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "共鳴波発生器で操られてるか、リプレイサーどもが創り出した崩壊体の失敗作だろうよ。"
L12_1.m_Talk_ENG = "They're either the Replacer collapsers from failed experiments, or the ones being controlled through the Resonance Pulse Generator."
L12_1.m_Talk_TWN = "不是利用共鳴裝置，就是克隆集團那些傢伙製造出的崩壞失敗品吧。"
L12_1.m_Talk_THA = "ถ้าไม่ใช่รีเพลสเซอร์ประเภทคอแลปเซอร์จากการทดลองที่ล้มเหลว ก็ต้องเป็นพวกที่ถูกควบคุมด้วยเครื่องกำเนิดเรโซแนนซ์พัลส์"
L12_1.m_Talk_VTN = "Chúng có thể là Người Nhân Bản Thất Bại từ các thí nghiệm thất bại hoặc là được điều khiển thông qua Máy Tạo Xung Cộng Hưởng.\n"
L12_1.m_Talk_SCN = "也许是利用（能晶）共鸣装置，或克隆集团那些家伙制造出来的崩坏体的失败品。"
L12_1.m_Talk_DEU = "Es handelt sich entweder um die Replacer-Zerborstenen aus fehlgeschlagenen Experimenten oder um solche, die über den Resonanzimpulsgenerator gesteuert werden."
L12_1.m_Talk_FRA = "Ce sont des anomalies des substituts qui soit proviennent de leurs expériences ratées, soit sont contrôlées par un générateur d'impulsions à résonance."
