L15_1.m_Pos = "C"
L15_1.m_Talk_KOREA = "그래서 어쩔 거야? 해결책을 내놔야지."
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "それで、どうするの？　解決策は？"
L15_1.m_Talk_ENG = "So what are we going to do? Give me a solution."
L15_1.m_Talk_TWN = "所以你打算怎麼辦？總要拿出個解決方法吧？"
L15_1.m_Talk_THA = "แล้วเราจะทำไงกันต่อ? ขอทางออกหน่อย"
L15_1.m_Talk_VTN = "Vậy chúng ta sẽ làm gì? Hãy cho tôi một giải pháp đi."
L15_1.m_Talk_SCN = "所以说你打算怎么办？总要拿出个解决办法吧？"
L15_1.m_Talk_DEU = "Was sollen wir tun? Mach einen Lösungsvorschlag."
L15_1.m_Talk_FRA = "Et donc que faisons-nous ? Donnez-moi une solution."
