L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 175
L18_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L18_1.m_Pos = "R"
L18_1.m_Talk_KOREA = "이봐, 아직도 의뢰인 기분을 내고 있는 건 아니겠지?"
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "おい、まだ依頼人のつもりじゃないよな？"
L18_1.m_Talk_ENG = "Hey, you're not thinking that you're still the client here, are you?"
L18_1.m_Talk_TWN = "喂，妳現在還抱著委託人的心態啊？"
L18_1.m_Talk_THA = "นี่ คุณคงไม่คิดว่าคุณยังเป็นลูกค้าอยู่ใช่ไหม?"
L18_1.m_Talk_VTN = "Này, bạn không nghĩ rằng bạn vẫn là khách hàng ở đây, phải không?"
L18_1.m_Talk_SCN = "喂，你不会现在还没有跳出委托人的思维吧？"
L18_1.m_Talk_DEU = "Glaubst du etwa, Du wärst hier noch der Kunde?"
L18_1.m_Talk_FRA = "Hé, vous ne pensez tout de même pas être toujours la cliente ici, hein ?"
L19_1 = {}
L19_1.m_CutScenKey_Talk = "EP5_ACT2_STAGE4_START@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 175
L19_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L19_1.m_Pos = "R"
L19_1.m_Talk_KOREA = "가끔은 직접 생각이라는 걸 해 보는 게 어때?"
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "たまには自分で考えてみたらどうだ？"
L19_1.m_Talk_ENG = "Why don't you do the thinking this time?"
L19_1.m_Talk_TWN = "偶爾也自己想想辦法如何？"
L19_1.m_Talk_THA = "ทำไมคราวนี้คุณไม่เป็นคนคิดบ้างล่ะ?"
L19_1.m_Talk_VTN = "Tại sao lần này bạn không suy nghĩ đi?"
L19_1.m_Talk_SCN = "偶尔，你也该有个自己的想法啊？"
L19_1.m_Talk_DEU = "Denk gefälligst selber nach."
L19_1.m_Talk_FRA = "Et si vous la trouviez vous-même la solution, pour une fois ?"
L20_1 = {}
L20_1.m_CutScenKey_Talk = "EP5_ACT2_STAGE4_START@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 175
L20_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_IDLE"
L20_1.m_CharStrID = "JANE_MASON_NULL_NULL"
L20_1.m_Pos = "L"
L20_1.m_Talk_KOREA = "흐응...... 뭐 그렇게 원한다면야 내 방식대로 진행해도 되는데 말이지."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "ふーん、まあそれがお望みなら、アタシのやり方でやってもいいんだけどね。"
L20_1.m_Talk_ENG = "Hmm... If that's what you want, I'd be glad to do this the way I normally handle things."
L20_1.m_Talk_TWN = "哼嗯……如果你這麼希望的話，那我就按照自己的方法來。"
L20_1.m_Talk_THA = "อืมม... ถ้าจะเอาอย่างนั้น ฉันก็จะยินดีจัดการเรื่องนี้ด้วยวิธีเดียวกับที่ฉันมักจัดการสิ่งต่างๆ"
L20_1.m_Talk_VTN = "Hmm ... Nếu đó là điều bạn muốn, tôi rất vui được làm điều này theo cách mà tôi thường xử lý mọi việc."
L20_1.m_Talk_SCN = "嗯……如果你那么想的话，也可以我的方式来。"
L20_1.m_Talk_DEU = "Hm … Wenn du darauf bestehst, können wir es gerne regeln, wie ich Dinge normalerweise regle …"
L20_1.m_Talk_FRA = "Hmm... si c'est ce que vous voulez, je serai ravie de faire les choses à ma manière."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "EP5_ACT2_STAGE4_START@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 175
