L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L21_1.m_Pos = "R"
L21_1.m_Talk_KOREA = "......미안하다."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "……俺が悪かった。"
L21_1.m_Talk_ENG = "Never mind."
L21_1.m_Talk_TWN = "……抱歉。"
L21_1.m_Talk_THA = "ช่างมันเถอะ"
L21_1.m_Talk_VTN = "Thôi bỏ đi."
L21_1.m_Talk_SCN = "……对不起。"
L21_1.m_Talk_DEU = "Ach, vergiss es. "
L21_1.m_Talk_FRA = "Oubliez ça."
L22_1 = {}
L22_1.m_CutScenKey_Talk = "EP5_ACT2_STAGE4_START@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 175
L22_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_DESPAIR"
L22_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L22_1.m_Pos = "R"
L22_1.m_Talk_KOREA = "내가 실언을 했군."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "失言だったよ。"
L22_1.m_Talk_ENG = "That didn't come out right."
L22_1.m_Talk_TWN = "是我失言了。"
L22_1.m_Talk_THA = "ผลลัพธ์มันไม่ได้ออกมาดีเลย"
L22_1.m_Talk_VTN = "Điều đó không đúng chút nào."
L22_1.m_Talk_SCN = "是我多事了。"
L22_1.m_Talk_DEU = "Das kam nicht richtig rüber."
L22_1.m_Talk_FRA = "C'est pas ce que j'ai voulu dire."
L23_1 = {}
L23_1.m_CutScenKey_Talk = "EP5_ACT2_STAGE4_START@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 175
L23_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L23_1.m_Pos = "R"
L23_1.m_Talk_KOREA = "제발 부탁이니까 <color=#ffd34c>네 방식</color>만큼은 좀 참아달라고."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "頼むから、<color=#ffd34c>あんたのやり方</color>だけは勘弁してくれよ。"
L23_1.m_Talk_ENG = "So please, do not handle anything <color=#ffd34c>in your way</color> during the operation."
L23_1.m_Talk_TWN = "算我求妳了，請妳克制一下<color=#ffd34c>妳的方式</color>吧。"
L23_1.m_Talk_THA = "ดังนั้นขอร้องละ อย่าจัดการกับอะไร<color=#ffd34c>ในแบบของคุณ</color>ระหว่างปฏิบัติการนะ"
L23_1.m_Talk_VTN = "Vì vậy, vui lòng không xử lý bất kỳ điều gì <color=#ffd34c>theo cách của bạn</color> trong quá trình tác chiến."
L23_1.m_Talk_SCN = "真的拜托了不要用<color=#ffd34c>你的方式</color>。"
L23_1.m_Talk_DEU = "Bitte regle während der Operation nichts so, <color=#ffd34c>wie du es normalerweise regelst</color>."
L23_1.m_Talk_FRA = "Ne faites pas les choses <color=#ffd34c>à votre manière</color> pendant l'opération, je vous prie."
L24_1 = {}
L24_1.m_CutScenKey_Talk = "EP5_ACT2_STAGE4_START@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 175
L24_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_LAUGH"
L24_1.m_CharStrID = "JANE_MASON_NULL_NULL"
L24_1.m_Pos = "L"
L24_1.m_Talk_KOREA = "하는 거 봐서 고려해 볼게."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "あなたの出方次第で考えてみるわ。"
L24_1.m_Talk_ENG = "I'll try."
L24_1.m_Talk_TWN = "我會看你的表現再決定怎麼做的。"
L24_1.m_Talk_THA = "จะพยายามนะ"
L24_1.m_Talk_VTN = "Tôi sẽ thử."
L24_1.m_Talk_SCN = "那得先看你怎么做，然后我再考虑一下看看。"
L24_1.m_Talk_DEU = "Ich werde es versuchen."
L24_1.m_Talk_FRA = "J'essaierai."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "EP5_ACT2_STAGE4_START@25#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 175
L25_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "JANE_MASON_NULL_NULL"
L25_1.m_Pos = "L"
L25_1.m_Talk_KOREA = "그래서 작전은?"
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "それで、作戦は？"
L25_1.m_Talk_ENG = "So, the plan?"
L25_1.m_Talk_TWN = "所以，你的作戰計畫呢？"
L25_1.m_Talk_THA = "สรุปแผนว่าไง?"
L25_1.m_Talk_VTN = "Vậy còn kế hoạch thì sao?"
L25_1.m_Talk_SCN = "所以说，你的作战方法呐?"
L25_1.m_Talk_DEU = "Also, was ist der Plan?"
L25_1.m_Talk_FRA = "Donc, le plan ?"
L26_1 = {}
L27_1 = "EP5_ACT2_STAGE4_START@26#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 26
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 175
L26_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_SERIOUS"
L26_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L26_1.m_Pos = "R"
L27_1 = "작전이라고 해 봐야 별거 있겠어?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "作戦といっても大したことはない。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "There's nothing to be called a plan."
L26_1.m_Talk_ENG = L27_1
L27_1 = "作戰能有什麼好說的？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ไม่มีแผนอะไรทั้งนั้น"
L26_1.m_Talk_THA = L27_1
L27_1 = "Không có kế hoạch gì cả."
L26_1.m_Talk_VTN = L27_1
L27_1 = "本来作战方法就没什么吧？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Es gibt nichts, was man einen Plan nennen könnte."
L26_1.m_Talk_DEU = L27_1
L27_1 = "On peut pas vraiment appeler ça un plan."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP5_ACT2_STAGE4_START@27#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 27
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 175
L27_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L27_1.m_Pos = "R"
L28_1 = "어차피 승부는 카운터들이 보는 거지."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "どっちみち勝負を決めるのはカウンターなんだ。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "It's Counters that are going to finish them off."
L27_1.m_Talk_ENG = L28_1
L28_1 = "反正勝負都是由制裁者決定的。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "เคาน์เตอร์จะเป็นคนจัดการพวกมัน"
L27_1.m_Talk_THA = L28_1
L28_1 = "Counter sẽ đến kết liễu chúng."
L27_1.m_Talk_VTN = L28_1
L28_1 = "反正胜负都是由制裁者决定的。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Die Counter werden ihnen den Garaus machen."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Ce sont les Counters qui vont les tuer."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "EP5_ACT2_STAGE4_START@28#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 28
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 175
L28_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L28_1.m_Pos = "R"
L29_1 = "우리가 일단 병력을 유인하는 동안 펜릴 소대 친구들이 공격을......"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "俺らが兵力を引き寄せてる間、フェンリル小隊が攻撃をかけて……"
L28_1.m_Talk_JPN = L29_1
L29_1 = "We lure the enemy forces away, then our allies of Fenrir Squad will catch them off guar—"
L28_1.m_Talk_ENG = L29_1
L29_1 = "我們先去引誘敵人，然後芬里爾小隊的夥伴們再進行攻擊……"
L28_1.m_Talk_TWN = L29_1
L29_1 = "เราจะล่อกองกำลังศัตรูออกไป จากนั้นพันธมิตรของเราจากหน่วยเฟนเรียร์ก็จะโจมตีแบบไม่ให้มันตั้งตัว..."
L28_1.m_Talk_THA = L29_1
L29_1 = "Chúng ta dụ quân địch bỏ chạy, sau đó các đồng minh của Tiểu Đội Fenrir sẽ bắt gọn chúng—"
L28_1.m_Talk_VTN = L29_1
L29_1 = "我们先去引诱兵力，芬里尔小队的伙伴们再来围剿……"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Wir locken die feindlichen Truppen zu uns, dann werden unsere Verbündeten vom Fenrir-Trupp sie überra–"
L28_1.m_Talk_DEU = L29_1
L29_1 = "On les attire plus loin, et nos amis de l'escouade Fenrir se chargeront de les prendre par su..."
L28_1.m_Talk_FRA = L29_1
