L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "艦船レベルの次元跳躍体の反応！　複数あり！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "There are ship-grade unidentified jumping objects coming this way! A lot of them!"
