L32_1 = "艦船級次元躍遷體反應！非常大量！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "มีวัตถุข้ามมิติที่ระบุเอกลักษณ์ไม่ได้คลาสยานรบกำลังมาทางนี้! เยอะเลยด้วย!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Có những Đối Tượng Nhảy Không Xác Định ở cấp độ chiến hạm đang đến theo hướng này! Rất nhiều luôn!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "舰船级次元跃迁体反应！好多！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Es kommen schiffsähnliche, nicht identifizierte, springende Objekte auf uns zu – und zwar viele!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Des objets non identifiés de type vaisseau sont en train de sauter dans notre direction ! Un gros paquet !"
