L51_1 = "どうもオルカたちに一発もらって逃げてきたようだ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Orca and others must have whacked them hard and made them flee here."
L50_1.m_Talk_ENG = L51_1
L51_1 = "不管怎麼看，都像是被奧爾卡一行人打得落荒而逃的樣子。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ออร์ก้ากับคนอื่นๆ คงเล่นงานพวกมันแรง ทำให้พวกมันหนีมาที่นี่"
L50_1.m_Talk_THA = L51_1
L51_1 = "Orca và những người khác chắc hẳn đã đánh cho chúng một vố đau và khiến chúng phải chạy trốn ở đây."
L50_1.m_Talk_VTN = L51_1
L51_1 = "看来是在奥尔卡他们那里受了不少攻击，逃过来的。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Orca und die anderen haben ihnen wahrscheinlich hart zugesetzt und sie hierher in die Flucht getrieben."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Orca et les autres ont dû leur mettre une raclée et les faire fuir jusqu'ici."
L50_1.m_Talk_FRA = L51_1
