L2_1 = "EP5_ACT2_STAGE4_START@51#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 51
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 175
L1_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_Face = "UNIT_IDLE"
L1_1.m_CharStrID = "JANE_MASON_NULL_NULL"
L1_1.m_Pos = "L"
L2_1 = "그럼 일이 더 쉬워진 거 아냐?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "だったら、もっと有利になったんじゃ？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Doesn't that mean our job has become easier?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "那事情不就變得簡單許多了嗎？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ไม่ได้แปลว่างานของเราง่ายขึ้นเหรอ?"
L1_1.m_Talk_THA = L2_1
L2_1 = "Điều đó không có nghĩa là công việc của chúng ta đã trở nên dễ dàng hơn phải không?"
L1_1.m_Talk_VTN = L2_1
L2_1 = "这样的话，不就简单多了吗？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Bedeutet das nicht, dass unsere Arbeit einfacher geworden ist?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Mais du coup c'est une bonne nouvelle, non ?"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "EP5_ACT2_STAGE4_START@52#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 52
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 175
L2_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "JANE_MASON_NULL_NULL"
L2_1.m_Pos = "L"
L3_1 = "뭐가 곤란한데?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "何がよくないの？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Why do you sound concerned?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "有什麼好傷腦筋的？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ทำไมนายฟังดูกังวลจัง?"
L2_1.m_Talk_THA = L3_1
L3_1 = "Tại sao bạn có vẻ lo lắng như vậy?"
L2_1.m_Talk_VTN = L3_1
L3_1 = "这有什么难的？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Warum klingst du so besorgt?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Pourquoi vous avez l'air si inquiet ?"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP5_ACT2_STAGE4_START@53#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 175
L3_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L3_1.m_Pos = "R"
L4_1 = "......당장이야 그렇겠지."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "……今は俺らが有利だが、"
L3_1.m_Talk_JPN = L4_1
L4_1 = "It's a good thing they're in confusion now."
L3_1.m_Talk_ENG = L4_1
L4_1 = "……現在應該是這樣沒錯。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "การที่พวกมันสับสนก็ดีนั่นละ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Thật tốt khi bây giờ chúng đang bối rối."
L3_1.m_Talk_VTN = L4_1
L4_1 = "……短时间内当然简单。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Gut, dass sie gerade so verwirrt sind."
L3_1.m_Talk_DEU = L4_1
L4_1 = "C'est une bonne chose qu'ils soient en plein désarroi."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP5_ACT2_STAGE4_START@54#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 54
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 175
L4_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L4_1.m_Pos = "R"
L5_1 = "하지만 놈들도 더 이상 물러설 곳이 없어."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "奴らもこれ以上逃げ場がないんだ。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "But this is their dead end."
L4_1.m_Talk_ENG = L5_1
L5_1 = "但那些傢伙已經沒有退路了。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แต่นี่คือทางตันของพวกมัน"
L4_1.m_Talk_THA = L5_1
L5_1 = "Nhưng đây sẽ là ngõ cụt của chúng."
L4_1.m_Talk_VTN = L5_1
L5_1 = "不过那些家伙，已经是没有退路了呀。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Aber das ist hier ist ihre letzte Chance."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Mais ils sont acculés."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP5_ACT2_STAGE4_START@55#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 55
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 175
L5_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L5_1.m_Pos = "R"
L6_1 = "여기에 있는 마지막 어보미네이션 융합체를 지키기 위해 필사적으로 달려들 거다."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "この最後のアボミネーション融合体を守るために、必死だろう。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "They'll do everything they can to protect the last Abomination they have left."
L5_1.m_Talk_ENG = L6_1
L6_1 = "他們就算是拼了命，也會守護這裡最後的憎惡融合體。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "พวกมันจะทำทุกอย่างเพื่อปกป้องอะบอมิเนชั่นสุดท้ายที่เหลืออยู่"
L5_1.m_Talk_THA = L6_1
L6_1 = "Chúng sẽ làm mọi điều để bảo vệ Abomination cuối cùng còn lại."
L5_1.m_Talk_VTN = L6_1
L6_1 = "他们会拼了命守护这个最后的“憎恶”融合体。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Sie werden alles tun, um die einzige Abscheulichkeit zu schützen, die sie noch haben."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Ils feront tout ce qu'ils peuvent pour protéger la dernière abomination qui leur reste."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "EP5_ACT2_STAGE4_START@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 175
L6_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L6_1.m_Pos = "R"
L7_1 = "어쩌면 증원군이 더 올 수도 있어."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "もしかすると、援軍がさらに来るかもしれんぞ。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Maybe they'll call for reinforcements."
L6_1.m_Talk_ENG = L7_1
L7_1 = "而且說不定還會有更多援軍過來。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "พวกมันอาจขอกำลังเสริม"
L6_1.m_Talk_THA = L7_1
L7_1 = "Có lẽ chúng sẽ gọi quân tiếp viện."
L6_1.m_Talk_VTN = L7_1
L7_1 = "可能还会有增援过来。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Vielleicht werden sie Verstärkung anfordern."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Ils vont peut-être appeler des renforts."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP5_ACT2_STAGE4_START@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 175
L7_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L7_1.m_bWaitClick = true
