L7_1.m_Face = "UNIT_IDLE"
L7_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L7_1.m_Pos = "R"
L8_1 = "아무래도...... 시간이 빠듯하겠는걸?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "こりゃ……時間的にきついかもな。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I'm afraid we won't have as much time as we expected."
L7_1.m_Talk_ENG = L8_1
L8_1 = "不管怎麼說……時間都非常緊湊吧？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ผมกลัวว่าเราจะมีเวลาไม่มากเท่ากับที่คาดการณ์ไว้"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tôi e rằng chúng ta sẽ không có nhiều thời gian như mong đợi."
L7_1.m_Talk_VTN = L8_1
L8_1 = "不管怎么说……给我们的时间不多了？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ich fürchte, wir werden nicht so viel Zeit haben, wie wir erwartet haben."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Je crains que nous ayons moins de temps que prévu."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "EP5_ACT2_STAGE4_START@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 175
L8_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "JANE_MASON_NULL_NULL"
L8_1.m_Pos = "L"
L9_1 = "그럼 결정됐네. 뭘 꾸물거리는 거야?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "それじゃあ、決まりね。なにグズグズしてんのよ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Then it's decided. What are you waiting for?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "那你還不快下決定，在這裡磨蹭什麼？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "งั้นก็ได้ข้อสรุปแล้ว จะมัวรออะไรอยู่ล่ะ?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Mọi thứ đã được quyết định rồi. Bạn còn chờ gì nữa?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "那就这么定了，磨蹭什么呢？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Dann ist klar, was wir zu tun haben. Worauf wartest du?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Bien dans ce cas, c'est décidé. Qu'est-ce que vous attendez ?"
L8_1.m_Talk_FRA = L9_1
