L16_1 = 30
L14_1[L15_1] = L16_1
L15_1 = "어이! 이봐! 어딜 가는 거야!!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "おい、どこに行くんだ！！"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Hey, hey! Where are you going?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "等一下！喂！妳要去哪啊！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "นี่ๆ! คุณจะไปไหนน่ะ?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Này, này! Bạn định đi đâu?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "喂！喂！你要去哪啊！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Hey! Wo gehst du hin?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Hé, hé ! Vous allez où comme ça ?"
L14_1.m_Talk_FRA = L15_1
