L16_1.m_Face = "UNIT_LAUGH"
L16_1.m_CharStrID = "JANE_MASON_NULL_NULL"
L17_1 = "C_L_M_I"
L16_1.m_Pos = L17_1
L17_1 = "우리가 미끼라며? 그럼 미끼 역할을 충실히 해야지!"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "アタシたちがエサなんでしょう？　だったら、エサ役をしっかり果たさなきゃ！"
L16_1.m_Talk_JPN = L17_1
L17_1 = "You said we were the bait. Then we try our best to look like the bait."
L16_1.m_Talk_ENG = L17_1
L17_1 = "你不是說我們是誘餌嗎？那就要忠實地去完成誘餌的任務啊！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "คุณบอกว่าเราเป็นเหยื่อล่อ งั้นเราก็ต้องพยายามเต็มที่ให้ดูเหมือนเหยื่อล่อสิ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Bạn đã nói chúng ta là mồi nhử. Vậy chúng ta phải cố gắng hết sức để trông giống như mồi nhử."
L16_1.m_Talk_VTN = L17_1
L17_1 = "你不是说我们是诱饵吗？那当然是去发挥诱饵的作用去啊！"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Du sagtest, wir seien Köder. Also sollten wir unser Bestes tun, um wie Köder auszusehen."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Vous avez dit que nous étions l'appât. Faisons de notre mieux pour avoir l'air d'un appât dans ce cas."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
