L17_1.m_Talk_ENG = L18_1
L18_1 = "快跟上！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เร็วเข้า รีบขยับตัวแล้วตามฉันมา!"
L17_1.m_Talk_THA = L18_1
L18_1 = "Nào, di chuyển đi và đến sau khi tôi!"
