L26_1 = "적습이다! 비상! 비상!"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "敵襲、敵襲だ！"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Enemy attack! We're under attack! We're under attack!"
L25_1.m_Talk_ENG = L26_1
L26_1 = "有敵人！ 緊急！緊急！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ศัตรูโจมตี! เราถูกโจมตี! เราถูกโจมตี!"
L25_1.m_Talk_THA = L26_1
L26_1 = "Kẻ thù tấn công! Chúng ta đang bị tấn công! Chúng ta đang bị tấn công!"
L25_1.m_Talk_VTN = L26_1
L26_1 = "出现敌人! 紧急！紧急！"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Feindlicher Angriff! Wir werden angegriffen! Wir werden angegriffen!"
L25_1.m_Talk_DEU = L26_1
L26_1 = "L'ennemi nous attaque ! Nous sommes attaqués ! Nous sommes attaqués !"
L25_1.m_Talk_FRA = L26_1
