L27_1 = "추격해! 절대로 화근을 남겨둬선 안 된다!"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "追いかけろ！　絶対に災いのもとを残してはならん！"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Chase her down! She'll come back with reinforcements if she gets out!"
L26_1.m_Talk_ENG = L27_1
L27_1 = "快追擊！絕對不能留下禍根！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ไล่ตามเธอไป! ถ้าเธอออกไปได้ เธอจะกลับมาพร้อมกำลังเสริม!"
L26_1.m_Talk_THA = L27_1
L27_1 = "Tìm bắt cô ta đi! Cô ta sẽ trở lại với quân tiếp viện nếu thoát ra ngoài!"
L26_1.m_Talk_VTN = L27_1
L27_1 = "给我追! 绝对不能留下祸根！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Verfolgt sie! Sie wird mit Verstärkung zurückkehren, wenn sie entkommt!"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Poursuivez-la ! Elle reviendra avec des renforts si elle parvient à s'enfuir !"
L26_1.m_Talk_FRA = L27_1
