L2_1 = "EP5_ACT2_STAGE4_START@101#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 101
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 175
L1_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L1_1.m_Pos = "C"
L2_1 = "그것도 지금이 그렇다는 거고 증원군이 얼마나 더 몰려올지 몰라."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "しかも、これは現状の話で、これからどれくらいの援軍が押し寄せてくるかわからない。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "And that's not all. Reinforcements will arrive, and God knows how powerful they're going to be."
L1_1.m_Talk_ENG = L2_1
L2_1 = "而且我們不知道他們還會有多少援軍過來。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "และยังไม่ใช่แค่นั้นนะ กำลังเสริมจะมาถึง และไม่มีใครรู้ว่าพวกมันจะแข็งแกร่งแค่ไหน"
L1_1.m_Talk_THA = L2_1
L2_1 = "Và đó không phải là tất cả. Quân tiếp viện sẽ đến, và Chúa mới biết chúng sẽ mạnh đến mức nào."
L1_1.m_Talk_VTN = L2_1
L2_1 = "而且现在还有一点：我们并不知道会来多少救援队。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Und das ist noch nicht alles: Es wird Verstärkung kommen – und Gott weiß, wie stark sie sein wird."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Et c'est pas tout. Des renforts vont arriver, et allez savoir à quel point ils seront puissants."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "EP5_ACT2_STAGE4_START@102#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 102
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 175
L2_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L2_1.m_Pos = "C"
L3_1 = "우리 같은 용병 나부랭이들이 버틸 수 있는 시간은 어차피 얼마 없어!"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "俺らのような傭兵が持ちこたえられるのは、どうせ後わずかしかない！"
L2_1.m_Talk_JPN = L3_1
L3_1 = "That means ordinary mercenaries like us won't be able to buy much time."
L2_1.m_Talk_ENG = L3_1
L3_1 = "像我們這樣的傭兵，是撐不了多久的。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "หมายความว่าทหารรับจ้างธรรมดาๆ อย่างพวกเราคงยื้อเวลาไม่ได้มากนัก"
L2_1.m_Talk_THA = L3_1
L3_1 = "Điều đó có nghĩa là những người lính đánh thuê bình thường như chúng ta sẽ không thể có nhiều thời gian."
L2_1.m_Talk_VTN = L3_1
L3_1 = "像我们这样的佣兵，不知道还能顶多久！"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Das bedeutet, dass gewöhnliche Söldner wie wir nicht in der Lage sein werden, viel Zeit zu gewinnen."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Ce qui veut dire que des mercenaires ordinaires comme nous n'allons pas pouvoir vous faire gagner beaucoup de temps."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP5_ACT2_STAGE4_START@103#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 175
L3_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L3_1.m_Pos = "C"
L4_1 = "그러니까 그 전에 너희들이 어떻게든 어보미네이션을......"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "だから、その前にどうにかあんたらがアボミネーションを……"
L3_1.m_Talk_JPN = L4_1
L4_1 = "So you must destroy the Abomination before we—"
L3_1.m_Talk_ENG = L4_1
L4_1 = "所以在這之前，你們再怎麼樣也要把憎惡給……"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ดังนั้นคุณต้องทำลายอะบอมิเนชั่นก่อนที่เราจะ..."
L3_1.m_Talk_THA = L4_1
L4_1 = "Vì vậy, bạn phải phá hủy Abomination trước khi chúng ta—"
L3_1.m_Talk_VTN = L4_1
L4_1 = "所以说，在这之前你们再怎么样也要把“憎恶”……"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Ihr müsst also die Abscheulichkeit zerstören, bevor wir–"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Vous allez donc devoir détruire l'abomination avant que..."
L3_1.m_Talk_FRA = L4_1
