L9_1 = "EP5_ACT2_STAGE4_START@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 175
L8_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L9_1 = "L_M_I"
L8_1.m_Pos = L9_1
L9_1 = "......이봐 소년, 지금 뭘 하는 거야?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "……おい、少年。何してるんだ？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "What do you think you're doing, boy?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "喂，少年，你現在在幹嘛啊？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ทำอะไรของคุณน่ะ พ่อหนุ่ม?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Anh bạn, anh nghĩ mình đang làm gì vậy?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "喂少年，你现在在干嘛啊？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Was glaubst du, was du da tust, Junge?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Qu'est-ce que tu fabriques, petit ?"
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "EP5_ACT2_STAGE4_START@109#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 175
L9_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L9_1.m_Pos = "L"
L10_1 = "너도 저 못 말리는 여자 흉내라도 내는 건가?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "あのブルドーザー女の真似でもしたいのか？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Are you trying to be a pain in my neck like that crazy woman?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "你也是在模仿那個勸不動的女人嗎？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "พยายามจะกวนฉันเหมือนผู้หญิงบ้าคนนั้นเหรอ?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Bạn đang cố gắng khiến tôi cảm thấy khó chịu như người phụ nữ điên đó phải không?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "是在模仿那个冲动的女人吗？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Willst du mir auf die Nerven gehen wie diese Verrückte?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Toi aussi tu essaies de me mettre en rogne comme l'autre folle ?"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "EP5_ACT2_STAGE4_START@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 175
L10_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L10_1.m_Pos = "L"
L11_1 = "m_Crash"
L12_1 = 40
L10_1[L11_1] = L12_1
L11_1 = "너희들이 나서는 건 우리가 먼저 미끼가 된 후라고!"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "あんたたちの出番は、俺らがエサになった後だぞ！"
L10_1.m_Talk_JPN = L11_1
L11_1 = "I told you, you Counters must wait until they take the bait!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "你們的登場時間是在我們當誘餌之後！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "บอกแล้วไง เคาน์เตอร์ต้องรอจนกว่าพวกนั้นจะฮุบเหยื่อ!"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tôi đã nói với bạn rồi, các Counter phải đợi cho đến khi chúng cắn câu!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "你们要出面，是在我们做诱饵之后！"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Ich habe doch gesagt, ihr Counter müsst warten, bis sie den Köder schlucken!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Je vous l'ai dit, vous devez attendre qu'ils mordent à l'hameçon."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EP5_ACT2_STAGE4_START@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 175
L11_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "R"
L12_1 = "......걱정 마세요 메이슨 씨."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "……心配はいりませんよ、メイソンさん。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Don't worry, Mr. Mason."
L11_1.m_Talk_ENG = L12_1
L12_1 = "……不用擔心。梅森先生。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ไม่ต้องห่วงนะ คุณเมสัน"
L11_1.m_Talk_THA = L12_1
L12_1 = "Đừng lo, ngài Mason."
L11_1.m_Talk_VTN = L12_1
L12_1 = "……不用担心梅森先生。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Nur keine Bange, John."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Ne vous inquiétez pas, Monsieur Mason."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "EP5_ACT2_STAGE4_START@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 175
L12_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "R"
L13_1 = "어차피 어보미네이션을 파괴하더라도......"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "どうせアボミネーションを破壊できたとしても……"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Even if we manage to destroy the Abomination,"
L12_1.m_Talk_ENG = L13_1
L13_1 = "反正就算破壞了憎惡……"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ต่อให้เราทำลายอะบอมิเนชั่นได้"
L12_1.m_Talk_THA = L13_1
L13_1 = "Ngay cả khi chúng ta cố gắng tiêu diệt Abomination,"
L12_1.m_Talk_VTN = L13_1
L13_1 = "反正就算破坏了“憎恶”也……"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Selbst wenn es uns gelingt, die Abscheulichkeit zu zerstören,"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Même si nous arrivons à détruire l'abomination,"
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP5_ACT2_STAGE4_START@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 175
L13_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "R"
L14_1 = "이곳에서 불멸체 코어의 차원간섭파를 관측하려면 방해꾼들이 없어야 하지 않나요?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ここで不滅体コアの次元干渉波を観測するためには、妨害勢力を排除したほうが良いのでは？"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I doubt we'd be able to observe the dimension interference waves of the Immortal System Core when they're still around."
L13_1.m_Talk_ENG = L14_1
L14_1 = "要能觀測到不滅者核心的次元干涉波，還是不可以有妨礙者吧？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ผมก็ไม่แน่ใจว่าเราจะสามารถสังเกตคลื่นแทรกระหว่างมิติ\nที่ส่งออกมาจากแกนระบบอิมมอร์ทอลได้ยังไง\nถ้าพวกมันยังอยู่แถวนี้"
L13_1.m_Talk_THA = L14_1
L14_1 = "Tôi nghi ngờ rằng liệu chúng ta có thể quan sát được sóng giao thoa chiều không gian của Lõi Hệ Thống Bất Diệt khi chúng vẫn ở xung quanh hay không."
L13_1.m_Talk_VTN = L14_1
L14_1 = "在这里，如果想观测不灭者核心的次元干涉波，是不是应该没有妨碍者？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "bezweifle ich, dass es uns gelingen wird, die Dimensionsinterferenzwellen des Kerns der Unsterblichkeitsmatrix zu erkennen, falls sie noch vorhanden sind."
L13_1.m_Talk_DEU = L14_1
L14_1 = "ça m'étonnerait qu'on puisse capter les interférences dimensionnelles du noyau du système immortel s'ils sont encore dans le coin."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
