L31_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "L"
L31_1 = "걱정 말아요, 미나 양."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "心配いりませんよ、ミナさん。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Trust me, Mina."
L30_1.m_Talk_ENG = L31_1
L31_1 = "這妳不用擔心，米娜小姐。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เชื่อใจผมสิ มีนา"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tin tôi đi, Mina."
L30_1.m_Talk_VTN = L31_1
L31_1 = "这你不用担心，米娜小姐。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Vertrau mir, Mina."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Fais-moi confiance, Mina."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP5_ACT2_STAGE4_START@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 175
L31_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "L"
L32_1 = "미나 양의 힘은 미나 양이 알고 있는 것보다 훨씬 강하니까요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ミナさんの実力は、ミナさんが思っているより、はるかに上ですから。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "You're much stronger than you give yourself credit for."
L31_1.m_Talk_ENG = L32_1
L32_1 = "米娜小姐的實力遠比米娜小姐自己想像的還要強。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เธอแข็งแกร่งกว่าที่เธอให้เครดิตตัวเองมากนะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Bạn mạnh mẽ hơn nhiều so với những gì bạn nghĩ."
L31_1.m_Talk_VTN = L32_1
L32_1 = "米娜小姐的实力远比你自己所知要强很多。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Du bist viel stärker, als du glaubst."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Tu es bien plus forte que tu le penses."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP5_ACT2_STAGE4_START@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 175
L32_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "L"
L33_1 = "애초에 저 불멸체 코어라는 것도 미나양에게서 추출한 클리포트 인자로 기동하고 있잖아요?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "あの不滅体コアというものも、ミナさんから抽出したクリフォト・ファクターによって起動してるわけですよね？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Think about it. A tiny bit of the Qliphoth Factor extracted from you was enough"
L32_1.m_Talk_ENG = L33_1
L33_1 = "不滅者核心在一開始，不也是用米娜小姐身上提取的逆卡巴拉因子啟動的嗎？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ลองคิดดูสิ คลิฟอธแฟกเตอร์แค่นิดหน่อยที่สกัดออกมาจากเธอนั้นมากพอแล้ว"
L32_1.m_Talk_THA = L33_1
L33_1 = "Hãy suy nghĩ về điều đó. Một mảnh nhỏ Nhân Tố Qliphoth được trích xuất từ bạn là đủ"
L32_1.m_Talk_VTN = L33_1
L33_1 = "从一开始那个所谓的“不灭者核心”，不就是由米娜小姐身上提取的神圣因子启动的吗？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Denk mal drüber nach. Ein winziges bisschen des Klippot-Faktors, der dir entzogen wurde, reichte aus,"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Réfléchis. Il a suffi d'un tout petit peu de ton agent qliphoth"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP5_ACT2_STAGE4_START@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 175
L33_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "L"
L34_1 = "그것도 겨우 극소량으로 말이죠."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "しかも、ほんのわずかな量で。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "to get the Immortal System Core running."
L33_1.m_Talk_ENG = L34_1
L34_1 = "雖然只有極少量就是了。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ที่จะทำให้แกนระบบอิมมอร์ทอลทำงานนะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "để chạy Lõi Hệ Thống Bất Diệt."
L33_1.m_Talk_VTN = L34_1
L34_1 = "而且是由极少量提取的。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "um den Kern der Unsterblichkeitsmatrix zum Laufen zu bringen."
L33_1.m_Talk_DEU = L34_1
L34_1 = "pour faire tourner le noyau du système immortel."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
