L36_1 = "m_Crash"
L35_1[L36_1] = 20
L36_1 = "하지만 난 그걸 쓰는 방법도...... 애초에 그게 뭔지도 모른다고!"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "でも、私自身はそれの使い方も……そもそもそれが何なのかも知らないんだよ！"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I don't even know what it is, let alone how to use it!"
L35_1.m_Talk_ENG = L36_1
L36_1 = "但是我連使用它的方法也……而且我甚至不知道它是什麼！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ฉันไม่รู้ด้วยซ้ำว่ามันคืออะไร วิธีใช้ก็ไม่รู้!"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tôi thậm chí không biết nó là gì, chứ đừng nói đến cách sử dụng nó!"
L35_1.m_Talk_VTN = L36_1
L36_1 = "但是我都不知道要怎么使用啊……甚至都不知道它是什么啊！"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ich weiß nicht mal genau, was es ist – geschweige denn, wie man es benutzt!"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Je ne sais même pas ce que c'est, et encore moins comment m'en servir !"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
