L38_1 = "没关系。我知道。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Kein Problem, ich werde dich führen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Ça va aller. Je vais te guider."
