L40_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "L"
L40_1 = "원하신다면 미나 양에게 잠들어 있는 클리포트 인자를 활성화시켜 드릴 수 있어요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "お望みなら、ミナさんのなかに眠っているクリフォト・ファクターを活性化することもできます。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "I can stimulate the Qliphoth Factor that lies asleep inside you, if you want."
L39_1.m_Talk_ENG = L40_1
L40_1 = "如果米娜小姐願意的話。我可以讓沉睡在米娜小姐體內的逆卡巴拉因子活性化。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ผมจำลองคลิฟอธแฟกเตอร์ที่หลับไหลอยู่ในตัวเธอได้นะ ถ้าเธอต้องการ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Tôi có thể kích thích Nhân Tố Qliphoth đang ngủ quên bên trong bạn, nếu bạn muốn."
L39_1.m_Talk_VTN = L40_1
L40_1 = "我可以让在熟睡中的神圣因子再次复苏，如果米娜小姐愿意的话。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ich kann den Klippot-Faktor, der in dir ruht, stimulieren – wenn du willst."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Je peux stimuler l'agent qliphoth qui sommeille en toi, si tu veux."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP5_ACT2_STAGE4_START@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 175
L40_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L40_1.m_bWaitClick = true
