L41_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "L"
L41_1 = "물론 아주 일부분이긴 하겠지만요."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "もちろん、ごく一部だけだとは思いますが。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "It'll be a very small part of it that's going to be active, but it'd be more than enough."
L40_1.m_Talk_ENG = L41_1
L41_1 = "當然，只是其中一部分而已。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ส่วนที่จะทำงานนั้นจะเป็นแค่ส่วนเล็กๆ เท่านั้น แต่แค่นั้นก็มากเกินพอแล้ว"
L40_1.m_Talk_THA = L41_1
L41_1 = "Chỉ một phần rất nhỏ của nó sẽ hoạt động, nhưng như vậy là quá đủ.\n"
L40_1.m_Talk_VTN = L41_1
L41_1 = "当然，只是其中很小的一部分。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Es würde zwar nur einen sehr kleinen Teil davon aktivieren, aber es wäre mehr als genug."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Il n'y aura qu'une toute petite partie qui sera active, mais ça devrait être largement suffisant."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
