L12_1 = "클리포트 인자인가 뭔가 하는 힘을 쓸 수 있게 해줘."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "クリフォト・ファクターとやらを使えるようにしてほしい。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Let me use the power of this Qliphoth thing."
L11_1.m_Talk_ENG = L12_1
L12_1 = "讓我能使用那個逆卡巴拉因子什麼的力量吧。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ฉันจะใช้พลังคลิฟอธอะไรนี่ก็ได้"
L11_1.m_Talk_THA = L12_1
L12_1 = "Hãy để tôi sử dụng sức mạnh của Qliphoth này."
L11_1.m_Talk_VTN = L12_1
L12_1 = "让我从神圣因子那里获得力量吧。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Lass mich die Kraft von diesem Klippot-Dingsbums nutzen."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Aide-moi à utiliser la puissance de ce machin qliphoth."
L11_1.m_Talk_FRA = L12_1
