L12_1.m_Pos = "R"
L13_1 = "지금의 내겐...... 그게 뭐든 힘이 필요해."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "今の私には……その力の正体が何であれ、必要だから。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "No matter how it may turn out, I need its power now."
L12_1.m_Talk_ENG = L13_1
L13_1 = "對現在的我來說……不管那是什麼，我都需要力量。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ไม่ว่ามันจะออกมาเป็นแบบไหน ฉันก็จำเป็นต้องใช้พลังนี้ตอนนี้"
L12_1.m_Talk_THA = L13_1
L13_1 = "Bất kể điều gì xảy ra, tôi cần sức mạnh của nó ngay bây giờ."
L12_1.m_Talk_VTN = L13_1
L13_1 = "对现在的我来说……需要的是力量。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Egal, wie es ausgeht – ich brauche diese Kraft jetzt."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Peu importe ce qui va se passer, j'ai besoin de sa puissance maintenant."
L12_1.m_Talk_FRA = L13_1
