L15_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "L"
L15_1 = "그럼 미나 양의 총 안에 숨겨진 그 이상한 검을 좀 꺼내 볼래요?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "じゃあ、ミナさんの銃の中の、その妙な剣を抜いてみてもらえますか？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Can you show me that unique blade hidden in your gun, please?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "那麼米娜小姐，能不能稍微請妳拔出槍裡那把奇怪的劍看看？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ขอดูใบมีดสุดพิเศษที่ซ่อนอยู่ในปืนของเธอหน่อยได้ไหม?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Hãy cho tôi xem lưỡi kiếm độc đáo được giấu trong khẩu súng của bạn được không?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "那米娜小姐能不能请你把枪里的那把奇怪的剑拔出来呐？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Zeig mir bitte die einzigartige Klinge, die in deiner Waffe versteckt ist."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Tu peux me montrer cette lame unique cachée dans ton fusil, s'il te plaît ?"
L14_1.m_Talk_FRA = L15_1
