L16_1 = "ん？　こ、これのこと……？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Huh? Y-you mean, this?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "什麼？這、這個嗎……？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "หืม? มะ-หมายถึงไอ้นี่น่ะเหรอ?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Hử? Ý bạn là, thứ này?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "哦？这，这个吗？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Hm? Die hier meinst du?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Hein ? T-Tu veux dire, ça ?"
