L16_1.m_Pos = "R"
L17_1 = "하지만...... 이 검을 잡고 있으면 금방 힘이 빠져서 오래 들고 있을 수가 없어......"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "でも……この剣を持ってるとすぐに体力を消耗しちゃって、長時間は持ってられないんだけど……"
L16_1.m_Talk_JPN = L17_1
L17_1 = "But this sword takes away my strength if I hold it for too long..."
L16_1.m_Talk_ENG = L17_1
L17_1 = "可是……只要握住這把劍，我很快就會沒力氣的，我沒辦法拿太久……"
L16_1.m_Talk_TWN = L17_1
L17_1 = "แต่ดาบนี้จะดูดพลังฉันไป ถ้าฉันถือมันไว้นานเกินไป..."
L16_1.m_Talk_THA = L17_1
L17_1 = "Nhưng thanh kiếm này sẽ lấy đi sức mạnh của tôi nếu tôi cầm nó quá lâu..."
L16_1.m_Talk_VTN = L17_1
L17_1 = "但是! 如果一直握住这把剑，我会很快没力气的，所以不能一直握着……"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Aber dieses Schwert raubt mir Kraft, wenn ich es zu lange halte …"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Mais la lame me vide de mes forces si je la tiens pendant trop longtemps..."
L16_1.m_Talk_FRA = L17_1
