L22_1 = "맨손으로 칼날을 잡으면 어떡해? 피가 나잖아?!"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "素手で刃を掴んでどうするのよ、出血してるじゃない！？"
