L22_1 = "You grabbed the blade with your bare hand! You're bleeding!"
L21_1.m_Talk_ENG = L22_1
L22_1 = "你幹嘛徒手抓住刀刃啊？你都流血了耶？！"
L21_1.m_Talk_TWN = L22_1
L22_1 = "นายจับดาบด้วยมือเปล่านะ! เลือดออกแล้ว!"
