L22_1 = "你怎么可以用手抓刀刃啊？你都出血了呀？！"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Du hast die Klinge mit der bloßen Hand angefasst! Du blutest!"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Tu as attrapé la lame à main nue ! Tu saignes !"
