L34_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = "m_Crash"
L34_1[L35_1] = 20
L35_1 = "어, 어떻게 된 거야?! 검에서...... 손을 뗄 수가 없어!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ど、どういうこと！？　剣から……手を離せない！"
L34_1.m_Talk_JPN = L35_1
L35_1 = "W-what's happening? I-I can't get my hands off the sword!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "怎、怎麼回事？劍……手沒辦法放開劍！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "กะ-เกิดอะไรขึ้น? ฉะ-ฉันปล่อยมือจากดาบไม่ได้!"
L34_1.m_Talk_THA = L35_1
L35_1 = "C-chuyện gì đang xảy ra vậy? T-tôi không thể bỏ tay ra khỏi thanh kiếm!"
L34_1.m_Talk_VTN = L35_1
L35_1 = "啊，这是怎么回事啊？在剑里……手没办法从剑上拿开了！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Was ist los? Ich kann das Schwert nicht loslassen!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Qu'est-ce qui se passe ? J-J'arrive pas à retirer mes mains de l'épée !"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP5_ACT2_STAGE4_START@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 175
L35_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "m_Crash"
L37_1 = 30
L35_1[L36_1] = L37_1
L36_1 = "무, 무슨 짓을 한 거야? 이게 대체......!"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "な、何をしたの？　これはいったい……！"
L35_1.m_Talk_JPN = L36_1
L36_1 = "W-what did you do, Shiyoon?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "你、你做了什麼？這到底是……!"
L35_1.m_Talk_TWN = L36_1
L36_1 = "นะ-นายทำอะไรลงไปน่ะ ชิยุน?"
L35_1.m_Talk_THA = L36_1
L36_1 = "B-bạn đã làm gì vậy, Shiyoon?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "你，你到底做了什么啊？这到底是怎么回事……!"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Was hast du getan, Shiyoon?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Qu'est-ce que tu as fait, Charles ?"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP5_ACT2_STAGE4_START@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 175
L36_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_IDLE"
L37_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "제 예상이 맞다면 그 검은 아마도 클리포트 인자를 동력으로 사용하는 무기일 겁니다."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "僕の予想どおりなら、その剣はクリフォト・ファクターを動力として使う武器でしょう。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "If I'm right, the sword is a weapon that draws power from the Qliphoth Factor."
L36_1.m_Talk_ENG = L37_1
L37_1 = "如果我猜得沒錯，這把劍也是以逆卡巴拉因子為動力的武器。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ถ้าผมคิดถูก ดาบคืออาวุธที่ดูดพลังมาจากคลิฟอธแฟกเตอร์"
L36_1.m_Talk_THA = L37_1
L37_1 = "Nếu tôi đúng, thanh kiếm là vũ khí hút sức mạnh từ Nhân Tố Qliphoth."
L36_1.m_Talk_VTN = L37_1
L37_1 = "如果我猜的没错的话这把剑也是以神圣因子为动力的武器。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Wenn ich richtig liege, ist das Schwert eine Waffe, die ihre Kraft aus dem Klippot-Faktor bezieht."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Si je ne me trompe pas, l'épée est une arme qui tire son pouvoir de l'agent qliphoth."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP5_ACT2_STAGE4_START@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 175
L37_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "그동안은 미나 양이 무의식 중에 활성화시킨 클리포트 인자의 파편만으로 기동하느라 대부분의 기능이 동결되어 있었던 것 같지만......"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "これまではミナさんが無意識に活性化させたクリフォト・ファクターの欠片だけで起動していたので、\n大半の機能が凍結されていたようですが……"
L37_1.m_Talk_JPN = L38_1
L38_1 = "It had most of its features disabled, not being able to pull enough power from the Qliphoth Factor fragment that you switched on unconsciously."
L37_1.m_Talk_ENG = L38_1
L38_1 = "到目前為止，米娜小姐都只是在無意識間，用逆卡巴拉因子的碎片啟動了這把劍，然而它大部分功能都被凍結了……"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ฟีเจอร์ส่วนใหญ่ของมันไม่ทำงาน ทำให้ไม่สามารถดึงพลังจากชิ้นส่วนคลิฟอธแฟกเตอร์ที่เธอเปิดโดยไม่รู้ตัวออกมาได้ไม่มากพอ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Nó đã bị vô hiệu hóa hầu hết các tính năng, không thể lấy đủ năng lượng từ mảnh Nhân Tố Qliphoth mà bạn đã bật một cách vô thức."
L37_1.m_Talk_VTN = L38_1
L38_1 = "之前是通过米娜小姐无意识中激活的一小部分神圣因子在启动，所以大部分功能都被冻结了……"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Die meisten seiner Funktionen waren deaktiviert, da es nicht genug Energie aus dem Klippot-Faktor-Fragment ziehen konnte, das du unbewusst eingeschaltet hattest."
L37_1.m_Talk_DEU = L38_1
L38_1 = "La plupart de ses fonctions sont désactivées, car elle est incapable de tirer suffisamment de puissance du fragment d'agent qliphoth que tu as libéré sans le vouloir."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP5_ACT2_STAGE4_START@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 175
L38_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L39_1 = "제 피에 녹아 있는 클리포트 인자를 직접 먹였으니 곧 완전히 깨어날 겁니다."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "僕の血に含まれているクリフォト・ファクターを直に吸収させたので、間もなく完全に目を覚ますでしょう。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "But now that it's fed on the Qliphoth Factor dissolved in my blood, it'll be fully awake shortly."
L38_1.m_Talk_ENG = L39_1
L39_1 = "但是當我親自餵了溶在我血裡的逆卡巴拉因子時，它應該很快就會醒過來了。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แต่ตอนนี้มันดูดพลังจากคลิฟอธแฟกเตอร์ที่ละลายปะปนอยู่ในเลือดของผม เดี๋ยวมันก็จะตื่นเต็มที่แล้วละ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Nhưng bây giờ nó đã được cung cấp Nhân Tố Qliphoth hòa tan trong máu của tôi, nó sẽ hoàn toàn thức tỉnh trong thời gian ngắn."
L38_1.m_Talk_VTN = L39_1
L39_1 = "但现在已经吸食了我血液中的神圣因子，所以马上会完全苏醒。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Aber nun hat es sich vom Klippot-Faktor genährt, der in meinem Blut aufgelöst war, und wird bald vollständig erwachen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Mais maintenant qu'elle s'est nourrie de l'agent qliphoth dilué dans mon sang, elle va se réveiller bientôt."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EP5_ACT2_STAGE4_START@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
