L40_1 = "m_Crash"
L39_1[L40_1] = 20
L40_1 = "......깨, 깨어나면 어떻게 되는데?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "……め、目覚めたらどうなるの？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "W-what happens if it wakes up?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "……醒、醒過來的話會怎麼樣？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "จะเกิดอะไรขึ้นถ้ามันตื่น?"
L39_1.m_Talk_THA = L40_1
L40_1 = "C-chuyện gì sẽ xảy ra nếu nó thức tỉnh?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "……天啊，那要是完全苏醒来了会怎么样啊？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Was passiert, wenn es erwacht?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Qu'est-ce qui va se passer si elle se réveille ?"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP5_ACT2_STAGE4_START@190#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 190
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 175
L40_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
