L41_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "그야 당연히 배가 고프다고 칭얼대겠죠."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "そりゃ当然、空腹を訴えてくるでしょうね。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "It would want to fill its empty stomach, of course."
L40_1.m_Talk_ENG = L41_1
L41_1 = "當然會餓得又哭又鬧啊。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "มันก็จะอยากเติมท้องที่ว่าง แน่นอนละ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Tất nhiên, nó sẽ muốn lấp đầy cái bụng rỗng của mình."
L40_1.m_Talk_VTN = L41_1
L41_1 = "当然会饿的又哭又闹啊。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Es wird seinen leeren Magen füllen wollen."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Elle va vouloir se remplir la panse, bien sûr."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP5_ACT2_STAGE4_START@191#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 175
L41_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L41_1.m_bWaitClick = true
