L42_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "C"
L42_1 = "제 피 몇 방울 정도로 그동안 쌓인 허기를 달래기에 부족할 테니까요."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "僕の血を数滴飲んだだけじゃ、これまでの空腹を満たすには不十分でしょうから。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "A few drops of my blood couldn't have been enough to satiate its hunger."
L41_1.m_Talk_ENG = L42_1
L42_1 = "畢竟才這麼幾滴血，要消除這段時間積累的饑餓感是不夠的。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เลือดของผมแค่สองสามหยดไม่พอดับกระหายให้มันหรอก"
L41_1.m_Talk_THA = L42_1
L42_1 = "Một vài giọt máu của tôi không thể đủ để thỏa mãn cơn đói của nó."
L41_1.m_Talk_VTN = L42_1
L42_1 = "因为就我这几滴血要消除这段时间积累的饥饿感是不够的呀。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ein paar Tropfen meines Blutes können nicht ausgereicht haben, um seinen Hunger zu stillen."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Quelques gouttes de mon sang n'ont pas pu la rassasier."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP5_ACT2_STAGE4_START@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 175
L42_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "그리고 이런 무기의 특성 상, 아마도 주인인 미나 양의 클리포트 인자를 빨아먹으려고 할 겁니다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "それにこういう武器の特徴として、持ち主であるミナさんのクリフォト・ファクターを欲しがると思います。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "And considering the common characteristics of a weapon like this, it'd want to suck on the Qliphoth Factor of its owner: you."
L42_1.m_Talk_ENG = L43_1
L43_1 = "而且這種武器的特性，可能就是想吸食主人米娜小姐的逆卡巴拉因子吧。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "และพอดูจากคุณสมบัติของอาวุธแบบนี้ มันจะต้องอยากดูดพลังคลิฟอธแฟกเตอร์ของเธอซึ่งเป็นเจ้าของแน่นอน"
L42_1.m_Talk_THA = L43_1
L43_1 = "Và xem xét các đặc điểm chung của loại vũ khí như thế này, nó sẽ muốn hút Nhân Tố Qliphoth của chủ nhân: chính là bạn."
L42_1.m_Talk_VTN = L43_1
L43_1 = "而且这种武器的特性，可能就是想吸食主人米娜小姐的神圣因子。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "In Anbetracht der üblichen Eigenschaften solcher Waffen würde es den Klippot-Faktor seines Besitzers aufsaugen wollen – und das bist du."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Et vu les caractéristiques communes des armes comme celle-ci, elle va vouloir aspirer l'agent qliphoth de son propriétaire : toi."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
