L51_1 = "<color=#ffd34c>여기는 선발대!</color>"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "<color=#ffd34c>こちらは先発隊！</color>"
L50_1.m_Talk_JPN = L51_1
L51_1 = "<color=#ffd34c>This is Recon.</color>"
L50_1.m_Talk_ENG = L51_1
L51_1 = "<color=#ffd34c>這裡是先遣隊！</color>"
L50_1.m_Talk_TWN = L51_1
