L50_1.m_Talk_THA = L51_1
L51_1 = "<color=#ffd34c>Trinh Sát Viên đây.</color>"
L50_1.m_Talk_VTN = L51_1
L51_1 = "<color=#ffd34c>我是先遣队！</color>"
