L2_1 = "<color=#ffd34c>매복해 있던 적을 발견했다!</color>"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "<color=#ffd34c>潜伏中の敵を見つけた！</color>"
L1_1.m_Talk_JPN = L2_1
L2_1 = "<color=#ffd34c>We've spotted enemies lying in ambush.</color>"
L1_1.m_Talk_ENG = L2_1
L2_1 = "<color=#ffd34c>發現埋伏的敵人！</color>"
L1_1.m_Talk_TWN = L2_1
L2_1 = "<color=#ffd34c>เราพบศัตรูดักซุ่มโจมตี</color>"
L1_1.m_Talk_THA = L2_1
L2_1 = "<color=#ffd34c>Chúng tôi phát hiện kẻ thù đang mai phục.</color>"
L1_1.m_Talk_VTN = L2_1
L2_1 = "<color=#ffd34c>发现敌军埋伏！</color>"
L1_1.m_Talk_SCN = L2_1
L2_1 = "<color=#ffd34c>Wir haben Feinde gesichtet, die einen Hinterhalt planen.</color>"
L1_1.m_Talk_DEU = L2_1
L2_1 = "<color=#ffd34c>Nous avons repéré les ennemis en position d'embuscade.</color>"
L1_1.m_Talk_FRA = L2_1
