L3_1 = "EP5_ACT2_STAGE4_START@202#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 202
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 175
L2_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "<color=#ffd34c>병력 구성은 카운터 두 명과 용병 다수로 판명!</color>"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "<color=#ffd34c>カウンター2名と複数の傭兵で構成されている！</color>"
L2_1.m_Talk_JPN = L3_1
L3_1 = "<color=#ffd34c>I see two Counters and multiple mercenaries.</color>"
L2_1.m_Talk_ENG = L3_1
L3_1 = "<color=#ffd34c>兵力構成為兩名制裁者，其餘大多數為傭兵！</color>"
L2_1.m_Talk_TWN = L3_1
L3_1 = "<color=#ffd34c>เห็นเคาน์เตอร์สองคนกับทหารรับจ้างหลายคน</color>"
L2_1.m_Talk_THA = L3_1
L3_1 = "<color=#ffd34c>Tôi thấy hai Counter và nhiều lính đánh thuê.</color>"
L2_1.m_Talk_VTN = L3_1
L3_1 = "<color=#ffd34c>敌方兵力有两名制裁者，其他大多数为佣兵！</color>"
L2_1.m_Talk_SCN = L3_1
L3_1 = "<color=#ffd34c>Ich sehe zwei Counter und mehrere Söldner</color>"
L2_1.m_Talk_DEU = L3_1
L3_1 = "<color=#ffd34c>Je dénombre deux Counters et de multiples mercenaires.</color>"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP5_ACT2_STAGE4_START@203#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 203
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 175
L3_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "<color=#ffd34c>쓸데없는 수작을 부리지 못하도록 처음부터 화력을 집중해서 단숨에 격멸하겠......</color>"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "<color=#ffd34c>余計なマネをされる前に、最初から火力を集中して一気に撃滅……</color>"
L3_1.m_Talk_JPN = L4_1
L4_1 = "<color=#ffd34c>We'll focus fire and eliminate them ASAP to prevent possible trouble—</color>"
L3_1.m_Talk_ENG = L4_1
L4_1 = "<color=#ffd34c>馬上集中火力，讓他們沒辦法耍花招，一舉殲滅他們……</color>"
L3_1.m_Talk_TWN = L4_1
L4_1 = "<color=#ffd34c>เราจะระดมยิงและกำจัดพวกมันทันที เพื่อป้องกันปัญหาในภายภาคหน้า...</color>"
L3_1.m_Talk_THA = L4_1
L4_1 = "<color=#ffd34c>Chúng ta sẽ tập trung hỏa lực và loại bỏ chúng càng sớm càng tốt để ngăn chặn sự cố có thể xảy ra—</color>\n"
L3_1.m_Talk_VTN = L4_1
L4_1 = "<color=#ffd34c>马上集中火力，让他们无法耍花招，一次性歼……</color>"
L3_1.m_Talk_SCN = L4_1
L4_1 = "<color=#ffd34c>Wir werden das Feuer auf sie richten und sie so möglichst schnell eliminieren, um möglichen Ärger–</color>"
L3_1.m_Talk_DEU = L4_1
L4_1 = "<color=#ffd34c>Nous allons concentrer nos tirs pour les éliminer dès que possible pour éviter d'éventuels probl...</color>"
L3_1.m_Talk_FRA = L4_1
