L9_1 = "<color=#ffd34c>여기는 HQ! 선발대! 무슨 일인가? </color>"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "<color=#ffd34c>こちらHQ！　先発隊！　どうした！</color>"
L8_1.m_Talk_JPN = L9_1
L9_1 = "<color=#ffd34c>This is HQ, Recon! What's going on? </color>"
L8_1.m_Talk_ENG = L9_1
L9_1 = "<color=#ffd34c>這裡是HQ！先遣隊！發生什麼事了？</color>"
L8_1.m_Talk_TWN = L9_1
L9_1 = "<color=#ffd34c>นี่ศูนย์บัญชาการ หน่วยลาดตระเวน! เกิดอะไรขึ้น?</color>"
L8_1.m_Talk_THA = L9_1
L9_1 = "<color=#ffd34c>HQ đây, Trinh Sát! Chuyện gì vậy?</color>"
L8_1.m_Talk_VTN = L9_1
L9_1 = "<color=#ffd34c>这里是总部！先遣队！发生了什么？</color>"
L8_1.m_Talk_SCN = L9_1
L9_1 = "<color=#ffd34c>Aufklärer, hier Hauptquartier! Was ist los? </color>"
L8_1.m_Talk_DEU = L9_1
L9_1 = "<color=#ffd34c>Reconnaissance, ici QG ! Que se passe-t-il ? </color>"
L8_1.m_Talk_FRA = L9_1
