L9_1[L10_1] = L11_1
L10_1 = "<color=#ffd34c>......응답하라! 선발대!!</color>"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "<color=#ffd34c>……応答せよ！　先発隊！！</color>"
L9_1.m_Talk_JPN = L10_1
L10_1 = "<color=#ffd34c>Come in, Recon!</color>"
L9_1.m_Talk_ENG = L10_1
L10_1 = "<color=#ffd34c>……快回答！先遣隊！</color>"
L9_1.m_Talk_TWN = L10_1
L10_1 = "<color=#ffd34c>ตอบสิ หน่วยลาดตระเวน!</color>"
L9_1.m_Talk_THA = L10_1
L10_1 = "<color=#ffd34c>Vào đi, Trinh Sát!</color>"
