L10_1.m_Face = "UNIT_IDLE"
L11_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "이런 건 예상하지 못했는데...... 하하......"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "これは想定外だな……ハハ……"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Well, this is something I didn't expect. Hah hah..."
L10_1.m_Talk_ENG = L11_1
L11_1 = "沒想到還會發生這種事情……哈哈……"
L10_1.m_Talk_TWN = L11_1
L11_1 = "นี่เป็นสิ่งที่ผมคาดไม่ถึงเลย ฮ่าๆ..."
L10_1.m_Talk_THA = L11_1
L11_1 = "Chà, đây là điều mà tôi không ngờ tới. Ha ha..."
L10_1.m_Talk_VTN = L11_1
L11_1 = "没料到还会发生这种事情啊……哈哈……"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Okay, damit hatte ich nicht gerechnet. Haha …"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Eh bien, je ne m'attendais pas à ça. Ha ha..."
L10_1.m_Talk_FRA = L11_1
