L12_1 = "EP5_ACT2_STAGE4_START@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 175
L11_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "제가 먹인 클리포트 인자를 모조리 태워서 외부로 방출해 버린 모양이군요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "僕が与えたクリフォト・ファクターを全て燃やして外部に放出してしまったようですね。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "It seems the sword has burnt off all the Qliphoth Factor I fed it and released it to the air."
L11_1.m_Talk_ENG = L12_1
L12_1 = "它把我餵的逆卡巴拉因子全部燒毀，排到外面了呢。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ดูเหมือนว่าดาบจะเผาไหม้คลิฟอธแฟกเตอร์ทั้งหมดที่ผมให้มันไป แล้วก็ปล่อยมันออกไปในอากาศ"
L11_1.m_Talk_THA = L12_1
L12_1 = "Có vẻ như thanh kiếm đã đốt cháy hết Nhân Tố Qliphoth mà tôi cho nó ăn và bay lên không trung."
L11_1.m_Talk_VTN = L12_1
L12_1 = "看来是把我给吃的神圣因子全部烧掉并排出去了。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Das Schwert hat offenbar den gesamten Klippot-Faktor, mit dem ich es gefüttert habe, ausgestoßen und in die Luft entlassen."
L11_1.m_Talk_DEU = L12_1
L12_1 = "On dirait que l'épée a consumé tout l'agent qliphoth que je lui avais donné et l'a libéré dans l'air."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "EP5_ACT2_STAGE4_START@212#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 212
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 175
L12_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "아마도 주인의 것이 아니면 불순물로 판정하는 것 같은데......"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "持ち主のものでないと、不純物とみなすようですが……"
L12_1.m_Talk_JPN = L13_1
L13_1 = "It's resisting taking in anything that's not from its owner."
L12_1.m_Talk_ENG = L13_1
L13_1 = "似乎不是主人的東西，就會被認定成是雜質……"
L12_1.m_Talk_TWN = L13_1
L13_1 = "มันต่อต้านการรับอะไรก็ตามที่ไม่ได้มาจากเจ้าของ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Nó chống lại việc tiếp nhận bất cứ thứ gì không phải từ chủ nhân của nó."
L12_1.m_Talk_VTN = L13_1
L13_1 = "似乎不是主人的东西会被认定是杂物……"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Es wehrt sich dagegen, etwas aufzunehmen, das nicht von seinem Besitzer stammt."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Elle refuse de prendre tout ce qui ne vient pas de sa propriétaire."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP5_ACT2_STAGE4_START@213#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 213
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 175
