L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L14_1 = "그 검, 대체 정체가 뭔지 점점 더 궁금해지는데요?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "その剣の正体、ますます気になりますね。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I'm becoming more and more curious where that sword really came from."
L13_1.m_Talk_ENG = L14_1
L14_1 = "那把劍，到底是什麼呢？我越來越好奇了。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ผมชักสงสัยขึ้นทุกทีแล้วว่าดาบนี้มาจากไหน"
L13_1.m_Talk_THA = L14_1
L14_1 = "Tôi càng ngày càng tò mò không biết thanh kiếm đó thực sự đến từ đâu."
L13_1.m_Talk_VTN = L14_1
L14_1 = "那把剑，到底是什么呢？我更好奇了。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Faszinierend! Ich möchte wissen, woher dieses Schwert wirklich stammt …"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Plus le temps passe, plus je suis curieux sur les véritables origines de cette épée."
L13_1.m_Talk_FRA = L14_1
