L16_1[L17_1] = L18_1
L17_1 = "여기는 HQ! 선발대의 연락이 끊어졌다!"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "こちらHQ！　先発隊の連絡が切れた！"
L16_1.m_Talk_JPN = L17_1
L17_1 = "This is HQ! We've lost contact with the recon troop."
L16_1.m_Talk_ENG = L17_1
L17_1 = "這裡是HQ！我們和先遣隊的聯絡中斷了！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "นี่ศูนย์บัญชาการ! เราขาดการติดต่อกับหน่วยลาดตระเวน"
L16_1.m_Talk_THA = L17_1
L17_1 = "HQ đây! Chúng tôi đã mất liên lạc với lính trinh sát."
L16_1.m_Talk_VTN = L17_1
L17_1 = "我是总部！我们和先遣队的联系中断了！"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Hier Hauptquartier! Wir haben den Kontakt zum Aufklärungstrupp verloren."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Ici le QG ! Nous avons perdu le contact avec les troupes de reconnaissance."
L16_1.m_Talk_FRA = L17_1
