L17_1.m_Talk_SCN = L18_1
L18_1 = "Panzerzug 2 und 3, die in der Nachhut bereitstehen, rücken sofort an die Front vor und–"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Pelotons blindés 2 et 3 en réserve, déployez-vous immédiatement sur la ligne de front et dé..."
L17_1.m_Talk_FRA = L18_1
