L20_1.m_CharStrID = L21_1
L21_1 = "R_M_I"
L20_1.m_Pos = L21_1
L21_1 = "자, 잠시만요, 사령관님! 신호가 들어옵니다!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "ちょ、ちょっと待ってください、司令官！　信号が入ります！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "C-Commander! We're receiving a transmission!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "等，等一下，司令官！有信號了！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ผะ-ผู้บัญชาการ! เราได้รับสัญญาณ!"
L20_1.m_Talk_THA = L21_1
L21_1 = "T-tổng tổng tư lệnh! Chúng tôi đang nhận được một đường truyền!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "等，等一下，司令官！有信号了！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "K-Kommandant! Wir empfangen eine Übertragung!"
L20_1.m_Talk_DEU = L21_1
