L23_1 = "m_StartFXSoundName"
L24_1 = "FX_CUTSCEN_NOISE"
L22_1[L23_1] = L24_1
L23_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "m_bCharHologramEffect"
L22_1[L23_1] = true
L23_1 = "<color=#ffd34c> 아아. 마이크 테스트...... 마이크 테스트...... 잘 들리시나요? 오버.</color>"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "<color=#ffd34c> あーあー、チェック・ワン・ツー、マイクテスト中、聞こえますか？ オーバー。</color>"
L22_1.m_Talk_JPN = L23_1
L23_1 = "<color=#ffd34c>Ah, ah. Mic test. One two, one two. Can you hear me? Over.</color>"
L22_1.m_Talk_ENG = L23_1
L23_1 = "<color=#ffd34c> 喂，喂。麥克風測試……麥克風測試……聽得見嗎？ 完畢。</color>"
L22_1.m_Talk_TWN = L23_1
L23_1 = "<color=#ffd34c>หนึ่ง สอง ทดสอบไมค์ หนึ่งสอง หนึ่งสอง ได้ยินไหม? เปลี่ยน</color>"
L22_1.m_Talk_THA = L23_1
L23_1 = "<color=#ffd34c> A, a. Kiểm tra mic. Một hai, một hai. Bạn có thể nghe thấy tôi không? Hết.</color>"
L22_1.m_Talk_VTN = L23_1
L23_1 = "<color=#ffd34c> 喂，喂。麦克风测试……麦克风测试……听得见吗？ 完毕。</color>"
L22_1.m_Talk_SCN = L23_1
L23_1 = "<color=#ffd34c>Ah-ha. Mikrofontest. Eins, zwei. Eins, zwei. Könnt ihr mich hören? Over.</color>"
L22_1.m_Talk_DEU = L23_1
L23_1 = "<color=#ffd34c>Ah, ah. Test. Un deux, un deux. Vous m'entendez ? À vous.</color>"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
