L26_1 = "SOLDIER_REPLACER_NULL_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "R"
L26_1 = "m_Crash"
L27_1 = 70
L25_1[L26_1] = L27_1
L26_1 = "뭣? 네놈은 누구냐? 어째서 네놈이 선발대의 무선통신기를......"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "なっ？　貴様は誰だ？　どうして貴様が先発隊の無線通信機を……"
L25_1.m_Talk_JPN = L26_1
L26_1 = "What? Who are you? And what are you doing with our radio device?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "什麼？你是誰？為什麼你會拿著先遣隊的無線對講機……"
L25_1.m_Talk_TWN = L26_1
L26_1 = "อะไร? นั่นใครน่ะ? แล้วทำอะไรกับอุปกรณ์วิทยุของเรา?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Cái gì? Bạn là ai? Và bạn đang làm gì với thiết bị radio của chúng tôi?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "什么？你们是谁？怎么会有先遣队的无线对讲机……"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Was? Wer bist du? Und was machst du mit unserem Funkgerät?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Quoi ? Qui êtes-vous ? Et que faites-vous sur nos lignes de communication ?"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP5_ACT2_STAGE4_START@226#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 226
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 175
L26_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "L"
L27_1 = "<color=#ffd34c>......시끄러워요, 엑스트라 여러분.</color>"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "<color=#ffd34c>……茶々を入れないでほしいですね、エキストラの皆さん。</color>"
L26_1.m_Talk_JPN = L27_1
L27_1 = "<color=#ffd34c>Shut it, Extras.</color>"
L26_1.m_Talk_ENG = L27_1
L27_1 = "<color=#ffd34c>……你們很吵耶，臨時演員們。</color>"
L26_1.m_Talk_TWN = L27_1
L27_1 = "<color=#ffd34c>เงียบน่า ตัวประกอบ</color>"
L26_1.m_Talk_THA = L27_1
L27_1 = "<color=#ffd34c>Tắt nó đi.</color>"
L26_1.m_Talk_VTN = L27_1
L27_1 = "<color=#ffd34c>……你们很吵诶，群众演员们。</color>"
L26_1.m_Talk_SCN = L27_1
L27_1 = "<color=#ffd34c>Haltet die Klappe, ihr Statisten.</color>"
L26_1.m_Talk_DEU = L27_1
L27_1 = "<color=#ffd34c>Taisez-vous, sous-fifres.</color>"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP5_ACT2_STAGE4_START@227#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 175
L27_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L27_1.m_bWaitClick = true
