L28_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "L"
L28_1 = "<color=#ffd34c>지금 미나 양이 아주 중요한 고비를 넘고 있는 중이거든요.</color>"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "<color=#ffd34c>今、ミナさんがとても重要なヤマを越えている最中なんです。</color>"
L27_1.m_Talk_JPN = L28_1
L28_1 = "<color=#ffd34c>Mina is currently getting over a very important hurdle in her life.</color>"
L27_1.m_Talk_ENG = L28_1
L28_1 = "<color=#ffd34c>米娜小姐現在正在跨越一個非常重要的難關呢。</color>"
L27_1.m_Talk_TWN = L28_1
L28_1 = "<color=#ffd34c>ตอนนี้มีนากำลังข้ามผ่านอุปสรรคที่สำคัญที่สุดในชีวิตของเธอ</color>"
L27_1.m_Talk_THA = L28_1
L28_1 = "<color=#ffd34c>Mina hiện đang cố gắng vượt qua một rào cản rất quan trọng trong cuộc đời.</color>"
L27_1.m_Talk_VTN = L28_1
L28_1 = "<color=#ffd34c>现在米娜小姐正在经历一个很重要的考验呢。</color>"
L27_1.m_Talk_SCN = L28_1
L28_1 = "<color=#ffd34c>Mina überwindet gerade eine sehr wichtige Hürde in ihrem Leben.</color>"
L27_1.m_Talk_DEU = L28_1
L28_1 = "<color=#ffd34c>Mina est en train de surmonter un obstacle très important dans sa vie.</color>"
L27_1.m_Talk_FRA = L28_1
