L41_1.m_fWaitTime = 0
L42_1 = "저, 적 카운터 아군 전열 내로 난입!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "て、敵のカウンターが味方の戦列内に乱入！"
L41_1.m_Talk_JPN = L42_1
L42_1 = "An enemy Counter has infiltrated our front line!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "敵，敵方制裁者亂入我方通信！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เคาน์เตอร์ศัตรูแทรกซึมเข้ามาในแนวหน้าของเราแล้ว!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Counter địch đã xuyên thủng tiền tuyến của chúng ta!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "有敌，敌方制裁者擅闯我军战斗队伍！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ein feindlicher Counter hat unsere Frontlinie infiltriert!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Un Counter ennemi a pénétré notre ligne de front !"
L41_1.m_Talk_FRA = L42_1
