L44_1 = "m_Crash"
L43_1[L44_1] = 20
L44_1 = "상대는 고작 카운터 한 명이다! 무슨 호들갑을 떠는 거야?!"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "相手は、たった一人のカウンターだ！　動揺してどうする！？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "It's just one Counter you're dealing with! What are you making a fuss about?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "那只是區區一個制裁者而已！有什麼好大驚小怪的？！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ก็แค่เคาน์เตอร์คนเดียว! โวยวายทำไมนักหนา?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Bạn chỉ phải xử lý một Counter thôi mà! Bạn ầm ĩ về cái gì cơ chứ?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "那只是一个制裁者而已！干什么咋咋呼呼的？！"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ihr habt es mit nur einem einzigen Counter zu tun! Warum macht ihr so einen Aufstand?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Ce n'est qu'un malheureux Counter isolé ! De quoi avez-vous peur ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
