L46_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "하, 하지만...... 저런 건 처음 봅니다! 너, 너무 빨라요!"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "で、ですが、あんなのは初めてです！　は、速すぎます！"
L46_1.m_Talk_JPN = L47_1
L47_1 = "B-but... I've never seen anything like that before! He's too fast!"
L46_1.m_Talk_ENG = L47_1
L47_1 = "但、但是……我第一次看見那樣的！他太、太快了！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ตะ-แต่... ฉันไม่เคยเห็นอะไรแบบนั้นมาก่อนเลย! เขาเร็วเกินไป!"
L46_1.m_Talk_THA = L47_1
L47_1 = "N-nhưng... tôi chưa từng thấy thứ gì như vậy trước đây! Hắn quá nhanh!"
L46_1.m_Talk_VTN = L47_1
L47_1 = "但，但是……我第一次看见那样的制裁者！太，太快了！"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Aber … so etwas habe ich noch nie gesehen! Er ist zu schnell!"
L46_1.m_Talk_DEU = L47_1
L47_1 = "M-Mais... Je n'ai jamais rien vu de tel ! Il est trop rapide !"
L46_1.m_Talk_FRA = L47_1
