L49_1 = "我們擋不住了！向本隊請求支援……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "เราต้านเขาไว้ไม่ได้! เรียกกำลังเสริมจากกองหลักเพื่อ..."
L48_1.m_Talk_THA = L49_1
L49_1 = "Chúng tôi không thể cản hắn lại! Gọi tiếp viện từ tổng bộ cho--"
L48_1.m_Talk_VTN = L49_1
L49_1 = "我们拦不住！向大部队请求支援……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Wir können ihn nicht aufhalten! Ruft Verstärkung für–"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Impossible de le retenir ! Demandez des renforts aux trou..."
