L15_1 = "EP5_ACT2_STAGE4_START@264#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 264
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 175
L14_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L14_1.m_Pos = "C"
L15_1 = "지금 내가 뭘 보고 있는 건지 좀 혼란스러운데......"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "今、俺の目に映っているものに戸惑ってるんだが……"
L14_1.m_Talk_JPN = L15_1
L15_1 = "I'm quite confused about what I'm seeing right now."
L14_1.m_Talk_ENG = L15_1
L15_1 = "我現在有點混亂，我到底看了什麼……"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ผมชักสับสนกับสิ่งที่เห็นแล้วละ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Tôi khá bối rối về những gì tôi đang nhìn thấy ngay bây giờ."
L14_1.m_Talk_VTN = L15_1
L15_1 = "现在我有点糊涂自己到底在看什么了……"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ich bin etwas verwirrt … Was geht hier gerade ab?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "J'ai du mal à comprendre ce que je suis en train de voir."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP5_ACT2_STAGE4_START@265#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 265
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 175
L15_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L15_1.m_Pos = "C"
L16_1 = "그동안은 힘을 숨기고 있었다...... 뭐 그런 건가?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "これまでは本来の力を隠していた……ってか？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Have you been hiding your true strength all along?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "你之前都是在隱藏實力……是這樣嗎？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "นี่คุณซ่อนพลังของตัวเองมาตลอดเหรอ?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Bạn đã che giấu sức mạnh thực sự của mình lâu như vậy sao?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "之前是在隐藏实力……是吧？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Hast du deine wahre Stärke die ganze Zeit verborgen?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Depuis tout ce temps, tu cachais ta véritable puissance ?"
L15_1.m_Talk_FRA = L16_1
