L19_1 = "EP5_ACT2_STAGE4_START@268#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 268
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 175
L18_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_LAUGH"
L19_1 = "m_StartFXSoundName"
L20_1 = "FX_CUTSCEN_FOOTSTEP_WALK_02"
L18_1[L19_1] = L20_1
L19_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L18_1.m_CharStrID = L19_1
L19_1 = "R_M_I"
L18_1.m_Pos = L19_1
L19_1 = "하하, 그럴리가요. 전 항상 최선을 다하고 있습니다만."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "ハハ、まさか。僕はいつだって最善を尽くしてますから。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Hah hah, no way. I've always been doing my best, you know."
L18_1.m_Talk_ENG = L19_1
L19_1 = "哈哈，怎麼可能。我一直都是全力以赴喔。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ฮ่าๆ เปล่าครับ ผมทำเต็มที่เสมอนะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Ha ha, không thể nào. Tôi luôn cố gắng hết sức, bạn biết đấy."
L18_1.m_Talk_VTN = L19_1
L19_1 = "哈哈，怎么可能。我总是竭尽全力的。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Haha, nein. Ich habe immer mein Bestes gegeben."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Ha ha, pas du tout. J'ai toujours fait de mon mieux, promis."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "EP5_ACT2_STAGE4_START@269#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 269
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 175
L19_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "R"
L20_1 = "그보다 미나 양이 검을 통제할 수 있게 되면 빨리 합류해달라고 전해주시겠어요?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "それより、ミナさんが剣をコントロールできるようになったら、早く合流するように伝えてくれますか？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "By the way, could you tell Mina that she'll need to join me as soon as she has the sword under control?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "比起這個，等米娜小姐能夠控制劍的時候，能告訴她要快點和我們會合嗎？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ว่าแต่คุณช่วยบอกมีนาได้ไหม ว่าเธอต้องตามผมมาให้ไวที่สุด ทันทีที่เธอควบคุมดาบเล่มนั้นได้?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Nhân tiện, bạn có thể nói với Mina rằng cô ấy sẽ cần tham gia cùng tôi ngay khi cô ấy có thể kiểm soát thanh kiếm không?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "话说回来，等米娜小姐掌握了控制剑的能力，可以让她赶紧和我们汇合吗？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Sag mal, kannst du Mina bitten, sich mir anzuschließen, sobald sie das Schwert unter Kontrolle hat?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Sinon, vous pourriez demander à Mina de me rejoindre dès qu'elle aura réussi à contrôler l'épée ?"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EP5_ACT2_STAGE4_START@270#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 270
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 175
L20_1.m_CutScenStrID = "EP5_ACT2_STAGE4_START"
L20_1.m_bWaitClick = true
