L21_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "R"
L21_1 = "시간 내에 놈들을 모두 처리하려면 서둘러야 할 테니까요."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "時間内に奴ら全員を始末するには、急がないといけませんから。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "We'll have to hurry to wipe them all out in time."
L20_1.m_Talk_ENG = L21_1
L21_1 = "要在時間內處理掉這些傢伙們，我們得快點才行。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "เราต้องรีบเก็บกวาดพวกมันให้หมดให้ทันเวลา"
L20_1.m_Talk_THA = L21_1
L21_1 = "Chúng ta phải nhanh chóng để quét sạch chúng kịp thời."
L20_1.m_Talk_VTN = L21_1
L21_1 = "要在限制时间之内处理掉这些家伙们，我们得抓紧了。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Wir müssen uns beeilen, um alle rechtzeitig zu eliminieren."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Nous devons nous dépêcher de les éliminer avant qu'il ne soit trop tard."
L20_1.m_Talk_FRA = L21_1
